  // Speicher-Verbrauch unabhängig von der History-Länge). Ältere Turns
  // bleiben in der DB persistent, nur eben nicht alle gleichzeitig in der
  // Browser-DOM. Wenn der Thread ein Compact-Item hat, hat das Vorrang
  // (Compact-Box + alles dahinter, älteres wird unterdrückt).
  const REPLAY_TURN_LIMIT = 1;
  let replayWhitelistTurns = null;   // null = alle (Live-Mode);
                                     // Set<turnId> = nur diese rendern
  let replayLatestInputTokens = 0;   // input_tokens des allerletzten Turns
                                     // — wird einmal final gesetzt, nicht per Event

  async function autoResumeLatestThread() {
    try {
      const r = await fetch(`${API}/v1/threads`);
      if (!r.ok) return;
      const threads = await r.json();
      if (!Array.isArray(threads) || threads.length === 0) return;
      const latest = threads[0];
      if (!latest || !latest.id) return;
      threadId = latest.id;
      $('thread-id').textContent = latest.id;
      $('thread-id').classList.add('live');

      // Thread-Detail holen → Turn-Liste, daraus die letzten N als Whitelist.
      let turnList = [];
      try {
        const dr = await fetch(`${API}/v1/threads/${latest.id}`);
        if (dr.ok) {
          const detail = await dr.json();
          turnList = Array.isArray(detail.turns) ? detail.turns : [];
        }
      } catch (e) { /* ignore — fällt auf "alle Events" zurück */ }

      // Turns chronologisch sortieren (älteste zuerst)
      turnList.sort((a, b) =>
        (a.created_at || '').localeCompare(b.created_at || '')
      );
      // Strategie: NICHTS aus der History rendern. Komplett leerer Chat
      // beim Reload. Egal wie viele Turns/Items in der DB liegen — wir
      // streamen sie nicht in den Browser zurück. Der Server-Kontext ist
      // davon unbetroffen (DB enthält alle Turns weiter; Compaction-State
      // ist serverseitig persistent).
      //
      // Folge: Beim Reload sieht der User einen leeren Chat mit Banner
      // ("X Turns in DB"). Sobald er was tippt, startet ein neuer Turn,
      // dessen Events live gerendert werden (per whitelistTurn-Call in
      // submit()).
      //
      // Älteres ist in der DB einsehbar: strix verlauf list / export.
      const trimmed = [];
      // Letzter Turn nur für die Context-Bar relevant (input_tokens-Wert)
      let compactIdx = -1;
      const lastTurn = turnList.length > 0 ? turnList[turnList.length - 1] : null;
      if (lastTurn) {
        const lastSum = (lastTurn.input_summary || '').toLowerCase();
        if (lastSum.includes('compact') ||
            lastSum.includes('compress') ||
            lastSum.includes('compaction')) {
          compactIdx = turnList.length - 1;
        }
        const u = lastTurn.usage || {};
        replayLatestInputTokens = u.input_tokens || 0;
        lastInputTokens = replayLatestInputTokens;
      }
      // Empty whitelist → shouldRenderEvent gibt für alle Turn-Events false zurück.
      // Nur Thread-Level-Events (turn_id=null) und in submit() per whitelistTurn()
      // hinzugefügte neue Turns rendern.
      replayWhitelistTurns = new Set();

      const empty = chat.querySelector('.empty-state');
      if (empty) empty.remove();
      if (latest.model) {
        const sel = $('model-select');
        for (const o of sel.options) {
          if (o.value === latest.model) { sel.value = latest.model; break; }
        }
      }

      // Status-Banner vor dem Replay
      const banner = document.createElement('div');
      banner.className = 'banner-err';
      banner.style.background = 'rgba(125,211,252,0.08)';
      banner.style.color = 'var(--accent)';
      banner.style.borderLeftColor = 'var(--accent)';
      banner.style.fontSize = '11px';
      const compactNote = compactIdx >= 0 ? ' · letzter Turn war Compact' : '';
      const ctxPct = lastInputTokens > 0
        ? ` · letzte Kontext-Auslastung: ${Math.round(lastInputTokens / 1048576 * 100)}%`
        : '';
      banner.innerHTML =
        `↻ Thread ${latest.id} fortgesetzt — <b>${turnList.length} Turns in DB${compactNote}</b>`
        + ctxPct
        + `<br><span style="font-size:10px; opacity:0.65">Verlauf wird nicht angezeigt (in DB erhalten). Neue Eingabe startet neuen Turn.</span>`;
      console.log('[autoResume]', {
        thread: latest.id,
        total_turns: turnList.length,
        compact_idx: compactIdx,
        whitelist_size: 0,
        last_input_tokens: lastInputTokens,
      });
      chat.appendChild(banner);
      setTimeout(() => banner.remove(), 30000);

      openStream(0);
      updateCtxBar();
    } catch (e) {
      console.warn('autoResume fehlgeschlagen:', e);
    }
  }

