async function submit() {
    const text = $('prompt').value.trim();
    if (!text) return;

    if (!threadId) {
      try { await createThread(); openStream(0); }
      catch (e) {
        const b = document.createElement('div');
        b.className = 'banner-err'; b.textContent = 'Thread-Create fehlgeschlagen: ' + e.message;
        chat.appendChild(b);
        return;
      }
    }
    // Remove empty-state on first message
    const empty = chat.querySelector('.empty-state');
    if (empty) empty.remove();

    appendUserMsg(text);
    showThinkingPlaceholder();
    $('prompt').value = '';
    autoresize();

    setBusy(true);
    startStallWatchdog();
    // Wenn der User direkt nach unten scrollt sobald er sendet — Stick wieder aktiv.
    stickToBottom = true;
    chat.scrollTop = chat.scrollHeight;

    try {
      const r = await fetch(`${API}/v1/threads/${threadId}/turns`, {
        method: 'POST',
        headers: {'Content-Type':'application/json'},
        body: JSON.stringify({ prompt: text }),
      });
      if (!r.ok) throw new Error(`HTTP ${r.status}: ${await r.text()}`);
      // Turn-ID merken für späteren Stop/Interrupt + Whitelist-Live
      const j = await r.json();
      currentTurnId = (j.turn && j.turn.id) || null;
      whitelistTurn(currentTurnId);
    } catch (e) {
      hideThinkingPlaceholder();
      const b = document.createElement('div');
      b.className = 'banner-err'; b.textContent = 'Turn-Send fehlgeschlagen: ' + e.message;
      chat.appendChild(b);
      maybeStickScroll();
      setBusy(false);
      clearStallWatchdog();
    }
  }

  // ─── UI events ───────────────────────────────────────────────────────────
  // Send/Stop ist ein Toggle: wenn ein Turn läuft, ist der Klick = Interrupt.
  $('send').addEventListener('click', () => {
    if (sending) stopCurrentTurn();
    else         submit();
  });
  $('compress-btn').addEventListener('click', () => { compressContext(); });
  $('model-select').addEventListener('change', () => { updateCtxBar(); });
  $('new-session').addEventListener('click', async () => {
    if (eventSource) { eventSource.close(); eventSource = null; }

