          if (presetSet.has(k.id)) continue;
          const o = document.createElement('option');
          o.value = k.id;
          o.textContent = k.ctx ? `${k.id}  (ctx ${(k.ctx/1024).toFixed(0)}K)` : k.id;
          sel.appendChild(o);
        }
      }
    } catch (e) {
      // Presets are already populated — no-op.
    }
    if (!sel.value && sel.options.length) sel.value = sel.options[0].value;
    updateCtxBar();
  }

